package com.fitforge.cardio;
import jakarta.persistence.*;import java.time.LocalDate;
@Entity @Table(name="cardio_goals",uniqueConstraints=@UniqueConstraint(name="uk_cardio_goal_owner_name",columnNames={"user_email","goal_name"}),indexes=@Index(name="idx_cardio_goal_owner",columnList="user_email"))
public class CardioGoal{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="user_email",nullable=false,length=190)private String userEmail;@Column(name="goal_name",nullable=false,length=80)private String goalName;@Column(name="target_distance_km")private Double targetDistanceKm;@Column(name="target_pace_min_km")private Double targetPaceMinPerKm;@Column(name="target_time_seconds")private Integer targetTimeSeconds;@Column(name="deadline_date",nullable=false)private LocalDate deadlineDate;@Column(name="original_deadline")private LocalDate originalDeadline;@Column(name="revised_deadline")private LocalDate revisedDeadline;
 protected CardioGoal(){}public CardioGoal(String email,CardioDtos.GoalInput i){userEmail=email;update(i);}public void update(CardioDtos.GoalInput i){goalName=i.goalName().trim();targetDistanceKm=i.targetDistanceKm();targetPaceMinPerKm=i.targetPaceMinPerKm();targetTimeSeconds=i.targetTimeSeconds();deadlineDate=i.deadlineDate();if(originalDeadline==null)originalDeadline=deadlineDate;revisedDeadline=deadlineDate;}public void reviseDeadline(LocalDate d){if(originalDeadline==null)originalDeadline=deadlineDate;revisedDeadline=d;}public Long getId(){return id;}public String getUserEmail(){return userEmail;}public String getGoalName(){return goalName;}public Double getTargetDistanceKm(){return targetDistanceKm;}public Double getTargetPaceMinPerKm(){return targetPaceMinPerKm;}public Integer getTargetTimeSeconds(){return targetTimeSeconds;}public LocalDate getDeadlineDate(){return deadlineDate;}public LocalDate getOriginalDeadline(){return originalDeadline==null?deadlineDate:originalDeadline;}public LocalDate getRevisedDeadline(){return revisedDeadline==null?deadlineDate:revisedDeadline;}
}
